  const stack = []; // indexes of the days still waiting for a warmer one
  for (let i = 0; i < temps.length; i++) {
    while (stack.length > 0 && temps[stack.at(-1)] < temps[i]) {
      const day = stack.pop();
      answer[day] = i - day;
    }
