#include <iostream>
#include <stack>
#include <vector>

std::vector<int> dailyTemperatures(const std::vector<int>& temps) {
    std::vector<int> answer(temps.size(), 0);
    std::stack<int> stack;  // indexes of the days still waiting for a warmer one
    for (int i = 0; i < static_cast<int>(temps.size()); i++) {
        while (!stack.empty() && temps[stack.top()] < temps[i]) {
            int day = stack.top();
            stack.pop();
            answer[day] = i - day;
        }
        stack.push(i);
    }
    return answer;
}

int main() {
    int n;
    std::cin >> n;
    std::vector<int> temps(n);
    for (int i = 0; i < n; i++) {
        std::cin >> temps[i];
    }
    std::vector<int> answer = dailyTemperatures(temps);
    for (std::size_t i = 0; i < answer.size(); i++) {
        if (i > 0) {
            std::cout << " ";
        }
        std::cout << answer[i];
    }
    std::cout << "\n";
    return 0;
}

