package main

import "fmt"

func dailyTemperatures(temps []int) []int {
	answer := make([]int, len(temps))
	stack := []int{} // indexes of the days still waiting for a warmer one
	for i, temp := range temps {
		for len(stack) > 0 && temps[stack[len(stack)-1]] < temp {
			day := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			answer[day] = i - day
		}
		stack = append(stack, i)
	}
	return answer
}

func main() {
	var n int
	fmt.Scan(&n)
	temps := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Scan(&temps[i])
	}
	answer := dailyTemperatures(temps)
	for i, x := range answer {
		if i > 0 {
			fmt.Print(" ")
		}
		fmt.Print(x)
	}
	fmt.Println()
}

