import { readFileSync } from "node:fs";

const input = readFileSync(0, "utf8");

function dailyTemperatures(temps: number[]): number[] {
  const answer = new Array<number>(temps.length).fill(0);
  const stack: number[] = []; // indexes of the days still waiting for a warmer one
  for (const [i, temp] of temps.entries()) {
    let day = stack.at(-1);
    while (day !== undefined && (temps[day] ?? temp) < temp) {
      stack.pop();
      answer[day] = i - day;
      day = stack.at(-1);
    }
    stack.push(i);
  }
  return answer;
}

const [n = 0, ...temps] = input.trim().split(/\s+/).map(Number);
console.log(dailyTemperatures(temps.slice(0, n)).join(" "));
